class Solution {
public:
    bool isThereAPath(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size(), length = m + n - 1;
        if (length % 2) return false;
        vector<vector<vector<char>>> dp(m, vector<vector<char>>(n, vector<char>(length + 1)));
        dp[0][0][grid[0][0]] = true;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == 0 && j == 0) continue;
                for (int k = grid[i][j]; k <= length; ++k) {
                    int previous = k - grid[i][j];
                    if (i && dp[i - 1][j][previous]) dp[i][j][k] = true;
                    if (j && dp[i][j - 1][previous]) dp[i][j][k] = true;
                }
            }
        }
        return dp[m - 1][n - 1][length / 2];
    }
};
